### Resumen Final de la Migración del `UsuarioController`

1.  **Estado Eliminado:** El nuevo controlador es **completamente stateless**. No hay campos de sesión. Cada petición es atómica y contiene toda la información necesaria.
2.  **Separación de Responsabilidades:**
    *   **DTOs:** Definen el contrato de datos con la vista y manejan la validación de formato.
    *   **Controlador:** Orquesta el flujo web. Recibe peticiones, invoca al servicio y decide qué vista mostrar. Es delgado y limpio.
    *   **Servicio:** Contiene toda la lógica de negocio. Es la parte más importante y ahora es fácilmente reutilizable y testeable de forma unitaria.
3.  **Seguridad Declarativa:** La autorización ya no es un `if` dentro de un método, sino una anotación clara (`@PreAuthorize`) que documenta y protege cada endpoint.
4.  **Mantenibilidad:** El código es ahora mucho más fácil de leer, depurar y extender. Añadir un nuevo campo al formulario de usuario es ahora una tarea trivial que solo implica modificar el DTO, el servicio y la vista, sin tocar la lógica compleja del controlador.

¡Has completado la migración de la lógica de negocio y control más compleja de tu aplicación! El siguiente paso sería la capa de presentación (migrar las vistas `.xhtml` a plantillas Thymeleaf `.html`), que usará estos nuevos controladores y DTOs para renderizar la interfaz de usuario.

package com.sena.dev.controllers;

import com.sena.dev.entities.Usuario;
import com.sena.dev.utils.SecurityUtil;
import java.io.Serializable;
import java.util.List;
import java.util.ArrayList;
import javax.inject.Named;
import javax.enterprise.context.SessionScoped;
import javax.faces.context.FacesContext;
import javax.servlet.http.HttpSession;

/**
 * Controller for dynamic navigation based on user roles
 * 
 * @author david
 */
@Named(value = "navigationController")
@SessionScoped
public class NavigationController implements Serializable {

    private List<MenuItem> menuItems;
    private Integer cachedUserId = null;

    public NavigationController() {
    }

    /**
     * Get current user from session
     */
    private Usuario getCurrentUser() {
        FacesContext facesContext = FacesContext.getCurrentInstance();
        if (facesContext != null) {
            HttpSession session = (HttpSession) facesContext.getExternalContext().getSession(false);
            if (session != null) {
                Object loginObj = session.getAttribute("login");
                if (loginObj instanceof LoginController) {
                    return ((LoginController) loginObj).getUsuarioActual();
                }
            }
        }
        return null;
    }

    /**
     * Get dynamic menu items based on user permissions (cached)
     */
    public List<MenuItem> getMenuItems() {
        Usuario currentUser = getCurrentUser();

        // Check if we need to rebuild the menu
        if (menuItems == null || currentUser == null || 
            !currentUser.getIdUsuario().equals(cachedUserId)) {
            menuItems = buildMenuItems();
            cachedUserId = currentUser != null ? currentUser.getIdUsuario() : null;
        }
        return menuItems;
    }

    /**
     * Build menu items based on user permissions
     */
    private List<MenuItem> buildMenuItems() {
        List<MenuItem> items = new ArrayList<>();
        Usuario currentUser = getCurrentUser();

        if (currentUser == null) {
            return items;
        }

        // Dashboard - always available for logged in users
        items.add(new MenuItem("Dashboard", "/welcome.xhtml", "fas fa-tachometer-alt"));

        // User management - only for users with USUARIOS permission
        if (SecurityUtil.hasModuleAccess(currentUser, "USUARIOS")) {
            items.add(new MenuItem("Usuarios", "/views/usuarios/index.xhtml", "fas fa-users"));
        }

        // Role management - only for admins
        if (SecurityUtil.isAdmin(currentUser)) {
            items.add(new MenuItem("Roles", "/views/roles/index.xhtml", "fas fa-user-tag"));
            items.add(new MenuItem("Permisos", "/views/permisos/index.xhtml", "fas fa-key"));
        }

        // Academic level management
        if (SecurityUtil.hasModuleAccess(currentUser, "NIVEL_ACADEMICO")) {
            items.add(new MenuItem("Niveles Académicos", "/views/nivelAcademico/index.xhtml", "fas fa-graduation-cap"));
        }

        // Institutions
        if (SecurityUtil.hasModuleAccess(currentUser, "INSTITUCIONES")) {
            items.add(new MenuItem("Instituciones", "/views/instituciones/index.xhtml", "fas fa-building"));
        }

        // Grades
        if (SecurityUtil.hasModuleAccess(currentUser, "GRADOS")) {
            items.add(new MenuItem("Grados", "/views/grados/index.xhtml", "fas fa-layer-group"));
        }

        // Groups
        if (SecurityUtil.hasModuleAccess(currentUser, "GRUPOS")) {
            items.add(new MenuItem("Grupos", "/views/grupos/index.xhtml", "fas fa-users-cog"));
        }

        // Classes
        if (SecurityUtil.hasModuleAccess(currentUser, "CLASES")) {
            items.add(new MenuItem("Clases", "/views/clases/index.xhtml", "fas fa-chalkboard-teacher"));
        }

        // Classrooms
        if (SecurityUtil.hasModuleAccess(currentUser, "AULAS")) {
            items.add(new MenuItem("Aulas", "/views/aulas/index.xhtml", "fas fa-door-open"));
        }

        return items;
    }

    /**
     * Refresh menu items (call this when user permissions change)
     */
    public void refreshMenu() {
        menuItems = null;
        cachedUserId = null;
    }

    /**
     * Check if user can access a specific module
     */
    public boolean canAccessModule(String module) {
        Usuario currentUser = getCurrentUser();
        return currentUser != null && SecurityUtil.hasModuleAccess(currentUser, module);
    }

    /**
     * Check if user can perform a specific operation
     */
    public boolean canPerformOperation(String module, String operation) {
        Usuario currentUser = getCurrentUser();
        return currentUser != null && SecurityUtil.canPerformOperation(currentUser, module, operation);
    }

    /**
     * Get user's display name
     */
    public String getUserDisplayName() {
        Usuario currentUser = getCurrentUser();
        if (currentUser != null) {
            return currentUser.getNombre() + " " + currentUser.getApellido();
        }
        return "";
    }

    /**
     * Get user's primary role
     */
    public String getUserPrimaryRole() {
        Usuario currentUser = getCurrentUser();
        if (currentUser != null) {
            com.sena.dev.entities.Rol primaryRole = SecurityUtil.getPrimaryRole(currentUser);
            return primaryRole != null ? primaryRole.getNombreRol() : "";
        }
        return "";
    }

    /**
     * Inner class for menu items
     */
    public static class MenuItem {
        private String name;
        private String url;
        private String icon;

        public MenuItem(String name, String url, String icon) {
            this.name = name;
            this.url = url;
            this.icon = icon;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public String getUrl() {
            return url;
        }

        public void setUrl(String url) {
            this.url = url;
        }

        public String getIcon() {
            return icon;
        }

        public void setIcon(String icon) {
            this.icon = icon;
        }
    }
}

¡Excelente! El `NavigationController` es una pieza central de la experiencia de usuario y un ejemplo perfecto de la diferencia fundamental entre el paradigma **stateful** de JSF/CDI (`@SessionScoped`) y el paradigma **stateless** de Spring Boot.

Vamos a desmantelar este componente y reconstruirlo de una manera moderna, eficiente y segura.

### Análisis del `NavigationController` Legacy

1.  **Stateful (`@SessionScoped`):** El principal problema. Almacena el menú del usuario en la sesión del servidor. Esto consume memoria y no escala bien en arquitecturas modernas (por ejemplo, con balanceadores de carga sin sesiones pegajosas).
2.  **Acoplamiento Fuerte:** Depende directamente de `FacesContext` y `HttpSession` para obtener al usuario. Esto lo hace inutilizable fuera de un contexto JSF/Servlet.
3.  **Lógica de Autorización Imperativa:** El método `buildMenuItems` es una larga cadena de `if (SecurityUtil.hasModuleAccess(...))`. La lógica de "quién puede ver qué" está codificada manualmente en el controlador.
4.  **Caché Manual:** Intenta optimizar guardando el menú en `menuItems` y usando `cachedUserId`, pero es una implementación de caché manual y propensa a errores.
5.  **Métodos Helper para la Vista:** Proporciona métodos como `canAccessModule` y `getUserDisplayName` que son llamados directamente desde las páginas `.xhtml`.

### El Enfoque Moderno con Spring Boot

Reemplazaremos este componente con una combinación de tres elementos:

1.  **Un DTO para el Menú:** La clase interna `MenuItem` es un buen DTO. La extraeremos y la modernizaremos.
2.  **Un Servicio (`NavigationService`):** Un servicio sin estado que contiene la lógica para construir el menú basado en los permisos del usuario actual.
3.  **Un `@ControllerAdvice`:** Un componente global de Spring que inyectará automáticamente el menú y la información del usuario en el `Model` de cada petición. **Esto reemplaza por completo la necesidad de una sesión.**

---

### Paso 7.1: Crear el DTO `MenuItemDTO`

Extraemos la clase `MenuItem` y la convertimos en un DTO de primer nivel en nuestro paquete `dto`.

**Nuevo Archivo: `src/main/java/com/edunekta/dev/dto/MenuItemDTO.java`**

```java
package com.edunekta.dev.dto;

import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * DTO para representar un elemento del menú de navegación.
 */
@Data
@AllArgsConstructor
public class MenuItemDTO {
    private String name;
    private String url;
    private String icon;
}
```

---

### Paso 7.2: Crear el `NavigationService`

Este servicio contendrá la lógica pura para construir el menú. No tendrá estado y será fácilmente testeable.

**Nuevo Archivo: `src/main/java/com/edunekta/dev/service/NavigationService.java`**

```java
package com.edunekta.dev.service;

import com.edunekta.dev.dto.MenuItemDTO;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

@Service
public class NavigationService {

    /**
     * Construye la lista de elementos del menú para el usuario autenticado.
     * Es sin estado: se llama en cada petición.
     * @param authentication El objeto de autenticación de Spring Security.
     * @return Una lista de MenuItemDTO.
     */
    public List<MenuItemDTO> getMenuItems(Authentication authentication) {
        List<MenuItemDTO> items = new ArrayList<>();

        // Obtener todos los permisos del usuario de una vez.
        Set<String> authorities = authentication.getAuthorities().stream()
                .map(GrantedAuthority::getAuthority)
                .collect(Collectors.toSet());

        // Dashboard - siempre disponible para usuarios autenticados
        items.add(new MenuItemDTO("Dashboard", "/welcome", "fas fa-tachometer-alt"));

        // Comprobaciones basadas en permisos de Spring Security
        // ¡Mucho más robusto y desacoplado que llamar a SecurityUtil!
        if (hasAnyAuthority(authorities, "PERM_USUARIOS_READ")) {
            items.add(new MenuItemDTO("Usuarios", "/usuarios", "fas fa-users"));
        }
        if (hasAnyAuthority(authorities, "ROLE_ADMIN")) {
            items.add(new MenuItemDTO("Roles", "/roles", "fas fa-user-tag"));
            items.add(new MenuItemDTO("Permisos", "/permisos", "fas fa-key"));
        }
        if (hasAnyAuthority(authorities, "PERM_NIVELES_ACADEMICOS_READ")) {
            items.add(new MenuItemDTO("Niveles Académicos", "/niveles-academicos", "fas fa-graduation-cap"));
        }
        // ... y así sucesivamente para los demás módulos ...
        // if (hasAnyAuthority(authorities, "PERM_INSTITUCIONES_READ")) { ... }

        return items;
    }

    /**
     * Helper para verificar si el usuario tiene al menos uno de los permisos dados.
     */
    private boolean hasAnyAuthority(Set<String> userAuthorities, String... requiredAuthorities) {
        for (String required : requiredAuthorities) {
            if (userAuthorities.contains(required)) {
                return true;
            }
        }
        return false;
    }
}
```

